   174    static FT_Bool
   175    find_base_glyph_record( FT_Byte*          base_glyph_begin,
   176                            FT_Int            num_base_glyph,
   177                            FT_UInt           glyph_id,
   178                            BaseGlyphRecord*  record )
   179    {
   180      FT_Int  min = 0;
   181      FT_Int  max = num_base_glyph - 1;
   182
   183
   184      while ( min <= max )
   185      {
   186        FT_Int    mid = min + ( max - min ) / 2;
   187        FT_Byte*  p   = base_glyph_begin + mid * BASE_GLYPH_SIZE;
   188
   189        FT_UShort  gid = FT_NEXT_USHORT( p );
   190
   191
   192        if ( gid < glyph_id )
   193          min = mid + 1;
   194        else if (gid > glyph_id )
   195          max = mid - 1;
   196        else
   197        {
   198          record->gid               = gid;
   199          record->first_layer_index = FT_NEXT_USHORT( p );
   200          record->num_layers        = FT_NEXT_USHORT( p );
   201
   202          return 1;
   203        }
   204      }
   205
   206      return 0;
   207    }
