   210    FT_LOCAL_DEF( FT_Error )
   211    tt_face_load_colr_layers( TT_Face          face,
   212                              FT_UInt          glyph_id,
   213                              FT_Glyph_Layer  *ret_layers,
   214                              FT_UShort*       ret_num_layers )
   215    {
   216      FT_Error   error;
   217      FT_Memory  memory = face->root.memory;
   218
   219      Colr*  colr = (Colr*)face->colr;
   220
   221      BaseGlyphRecord  glyph_record;
   222      FT_Glyph_Layer   layers = NULL;
   223      int              layer_idx;
   224      FT_Byte*         layer_record_ptr;
   225
   226
   227      if ( !ret_layers || !ret_num_layers )
   228        return FT_THROW( Invalid_Argument );
   229
   230      if ( !find_base_glyph_record( colr->base_glyphs,
   231                                    colr->num_base_glyphs,
   232                                    glyph_id,
   233                                    &glyph_record ) )
   234      {
   235        *ret_layers     = NULL;
   236        *ret_num_layers = 0;
   237
   238        return FT_Err_Ok;
   239      }
   240
   241      /* Load all colors for the glyphs; this would be stored in the slot. */
   242      layer_record_ptr = colr->layers +
   243                         glyph_record.first_layer_index * LAYER_SIZE;
   244
   245      if ( FT_NEW_ARRAY( layers, glyph_record.num_layers ) )
   246        goto Error;
   247
   248      for ( layer_idx = 0; layer_idx < glyph_record.num_layers; layer_idx++ )
   249      {
   250        FT_UShort  gid                 = FT_NEXT_USHORT( layer_record_ptr );
   251        FT_UShort  palette_entry_index = FT_NEXT_USHORT( layer_record_ptr );
   252
   253
   254        if ( palette_entry_index != 0xFFFF                                 &&
   255             palette_entry_index >= face->palette_data.num_palette_entries )
   256        {
   257          error = FT_THROW( Invalid_Table );
   258          goto Error;
   259        }
